interface Message {
  role: "user" | "assistant";
  content: string;
  /** assistant 메시지의 서버 ID (done event에서 받음). reaction 호출에 사용. */
  id?: string;
  /** 1 = like, -1 = dislike, undefined = 미반응. */
  reaction?: 1 | -1;
  /** 신고 완료 표시 (UI 잠금). 서버 응답 200 받은 후 true. */
  reported?: boolean;
  /** 진행 단계 표시: 첫 delta 도착 또는 done 시 비워짐. */
  progress?: ProgressState;
  /** 챗봇이 전달한 파일. 서버가 검증한 것만 온다. */
  files?: AttachedFile[];
}

/**
 * 답변에 첨부된 파일.
 *
 * URL 이 아니라 id 를 담는다. 서버가 매 요청 권한을 확인하고 단기 서명 URL 을
 * 새로 만들어 주므로, 대화를 저장해 두었다가 나중에 열어도 링크가 죽지 않는다.
 */
interface AttachedFile {
  id: string;
  name: string;
  label: string;
  mimeType: string;
  size: number;
  isImage: boolean;
}

/** SSE progress 이벤트로 갱신되는 상태, UI 상단 status 라인. */
interface ProgressState {
  /** thinking | tool_start | tool_progress | tool_done | streaming */
  stage: string;
  /** 사람에게 보여줄 텍스트. */
  text: string;
  /** 검색 도구 호출이 끝난 누적 단계: 사용자가 답변과 함께 진행 이력을 볼 수 있게. */
  history: string[];
}

